import (
	"fmt"
	"os"
	"strings"

	"github.com/spf13/viper"
)

func main() {
	// Clear any existing env vars
	os.Unsetenv("APG_REGISTRY_ADDRESS")
	os.Unsetenv("REGISTRY_ADDRESS")

	// Set both
	os.Setenv("APG_REGISTRY_ADDRESS", "localhost:8080")
	os.Setenv("REGISTRY_ADDRESS", "localhost:9090")

	// Simulate what ReadValid does
	v := viper.New()
	v.AutomaticEnv()
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.SetEnvPrefix("")  // empty prefix now
	v.BindEnv("registry.address")

	// Check values
	fmt.Printf("v.GetString('registry.address'): '%s'\n", v.GetString("registry.address"))

	deprecatedVar := "APG_REGISTRY_ADDRESS"
	currentVar := "REGISTRY_ADDRESS"

	deprecatedValue, exists := os.LookupEnv(deprecatedVar)
	fmt.Printf("Deprecated var %s exists: %v, value: %s\n", deprecatedVar, exists, deprecatedValue)

	newValue, newEnvSet := os.LookupEnv(currentVar)
	fmt.Printf("Current var %s exists: %v, value: %s\n", currentVar, newEnvSet, newValue)

	if !newEnvSet {
		fmt.Println("Would use deprecated value")
	} else if newValue == deprecatedValue {
		fmt.Println("Both set to same value")
	} else {
		fmt.Println("New env var takes precedence - would NOT override")
	}
}
